import{_ as t,H as a,f as r,i as o}from"./chunks/framework.B05LFaXs.js";const p=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"dev/contributing/index.md","filePath":"dev/contributing/README.md"}'),i={name:"dev/contributing/index.md"};function n(s,e,l,c,u,h){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to &quot;Contributing&quot;">​</a></h1><p>Thanks you for your interest in contributing to CaSS.</p><p>Additional governance documentation is available on the <a href="https://github.com/cassproject/CASS/community" target="_blank" rel="noreferrer">GitHub Community Page</a> for CaSS.</p><h2 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h2><p>Before you contribute, please connect with the CaSS Project group by subscribing to the slack channel, joining the mailing lists, and joining the <em>#dev</em> channel on Slack. Once you have joined the group, please introduce yourself by telling us who you are and what type of contributions you are interested in making. We welcome contributions of:</p><ul><li>Issues</li><li>Tools or applications that use CaSS Libraries</li><li>Libraries or adapters that enable CaSS to integrate with third party applications</li><li>CaSS Project or CaSS Library code</li><li>Documentation and guides</li></ul><p>Please note that all contributions will be reviewed by the governance team or technical advisory group of the CaSS Project.</p><h2 id="getting-help" tabindex="-1">Getting Help <a class="header-anchor" href="#getting-help" aria-label="Permalink to &quot;Getting Help&quot;">​</a></h2><p>If you get stuck or find a problem, please file a GitHub and, for more immediate help, contact us via Slack or by emailing <a href="mailto:cass@eduworks.com" target="_blank" rel="noreferrer">us</a>.</p><h2 id="development-stack" tabindex="-1">Development Stack <a class="header-anchor" href="#development-stack" aria-label="Permalink to &quot;Development Stack&quot;">​</a></h2><p>The CASS Library is a Javascript Library, and is available in <a href="https://github.com/cassproject/cass-npm" target="_blank" rel="noreferrer">GitHub</a>, <a href="https://www.npmjs.com/package/cassproject" target="_blank" rel="noreferrer">NPM</a> and <a href="https://bower.io/search/?q=cassproject" target="_blank" rel="noreferrer">Bower</a>.</p><p>The preferred development environment is not specified, but we tend to use Visual Studio Code.</p><h2 id="governance" tabindex="-1">Governance <a class="header-anchor" href="#governance" aria-label="Permalink to &quot;Governance&quot;">​</a></h2><ul><li>The CaSS Project is an open source community governed by <a href="https://www.eduworks.com" target="_blank" rel="noreferrer">Eduworks Corporation</a> (&quot;Eduworks&quot;).</li><li>The CaSS website, documentation, and GitHub project are managed by Eduworks.</li><li>The CaSS Project accepts contributions in the form of pull requests, communications, suggestions, documents, and issues via GitHub.</li><li>All contributors must sign a CaSS Project CLA prior to making any contribution outside of GitHub. The CaSS Project CLAs are similar to the Individual and Corporate Apache Contributor License Agreements. Please email <a href="mailto:cass@eduworks.com" target="_blank" rel="noreferrer">us</a> for a CLA.</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><p>The CaSS Architecture Slides document, available <a href="https://docs.google.com/presentation/d/1P5SR93EPrxjbTRKfz70tmBXmmsH0JjxKvoZR-70UDsg" target="_blank" rel="noreferrer">here</a>, is a useful set of visualizations for understanding CaSS and its architecture.</p><h2 id="contributing-1" tabindex="-1">Contributing <a class="header-anchor" href="#contributing-1" aria-label="Permalink to &quot;Contributing&quot;">​</a></h2><p>To contribute changes to CaSS, please clone the project to your GitHub and submit changes from your clone to the main project via Pull Requests. To contribute new libraries or software, please devolop the code on GitHub and assign your project to the CaSS Project Group when complete.</p><p>All contributions will be reviewed by Eduworks. Commits of accepted contributions will be made by Eduworks.</p><p>To contribute other resources, please contact <a href="mailto:cass@eduworks.com" target="_blank" rel="noreferrer">us</a>.</p>',20)])])}const b=t(i,[["render",n]]);export{p as __pageData,b as default};
